use super::*;

/// Trimmed from a real GIPHY page (2026-10-09): meta tags plus embedded data
/// holding this GIF's record and a related GIF's tags.
const PAGE: &str = r#"<html><head>
<meta property="og:title" content="Tmkoc GIF - Find &amp; Share on GIPHY"/>
<meta property="og:image" content="https://media1.giphy.com/media/v1.Y2lkPTc5MGI3NjEx/SinIpWR8Jc6VVIdwNy/giphy.webp"/>
</head><body><script>self.__next_f.push([1,"{\"gifs\":[{\"id\":\"OTHER1\",\"rating\":\"pg\",\"tags\":[\"jethalal hairs\",\"tmkoc hairs\"]},{\"id\":\"SinIpWR8Jc6VVIdwNy\",\"rating\":\"g\",\"tags\":[\"giphycreatortest\",\"tmkoc\",\"jethalal\",\"chup ho ja satvi fail\"]}]}"])</script></body></html>"#;

const URL: &str = "https://giphy.com/gifs/tmkoc-jethalal-chup-ho-ja-satvi-fail-SinIpWR8Jc6VVIdwNy";

#[test]
fn gif_ids_come_only_from_single_gif_pages() {
    assert_eq!(giphy_gif_id(URL), Some("SinIpWR8Jc6VVIdwNy"));
    assert_eq!(giphy_gif_id("https://giphy.com/explore/indian"), None);
    assert_eq!(
        giphy_gif_id("https://tenor.com/search/indian-party-gifs"),
        None
    );
}

#[test]
fn a_real_page_yields_small_media_rating_tags_and_slug() {
    let found = parse_giphy_page(URL, PAGE).unwrap();
    assert_eq!(found.title, "Tmkoc GIF");
    assert_eq!(
        found.media_url,
        "https://media1.giphy.com/media/v1.Y2lkPTc5MGI3NjEx/SinIpWR8Jc6VVIdwNy/200.webp"
    );
    // This GIF's own record, not the related GIF listed first.
    assert_eq!(found.rating.as_deref(), Some("g"));
    assert!(found.tags.contains(&"chup ho ja satvi fail".to_owned()));
    assert!(!found.tags.contains(&"tmkoc hairs".to_owned()));
    assert_eq!(
        found.slug_words,
        ["tmkoc", "jethalal", "chup", "ho", "ja", "satvi", "fail"]
    );
}

#[test]
fn media_from_other_hosts_is_refused() {
    let page = PAGE.replace("media1.giphy.com", "evil.example");
    assert!(parse_giphy_page(URL, &page).is_none());
}

use super::*;
use std::sync::Mutex;

struct Hits(Mutex<Vec<String>>);

#[async_trait]
impl WebSearch for Hits {
    async fn search(&self, query: &str, _max: usize) -> Result<Vec<SearchHit>, BoxError> {
        self.0.lock().unwrap().push(query.to_owned());
        Ok(vec![SearchHit {
            title: "Hinglish slang guide".into(),
            url: "https://slang.example/guide/".into(),
            snippet: Some("bawaal: chaos; scene set hai: all arranged".into()),
        }])
    }
}

struct Model;

#[async_trait]
impl ChatModel for Model {
    async fn complete(&self, system: &str, _user: &str) -> Result<String, BoxError> {
        if system.starts_with("Turn the request") {
            return Ok("hinglish slang for job offer".into());
        }
        Ok(r#"{"terms": [
            {"term": "bawaal", "meaning": "chaos", "intensity": "spicy", "source_url": "https://slang.example/guide"},
            {"term": "made up", "meaning": "x", "intensity": "light", "source_url": "https://elsewhere.example/"}
        ]}"#
        .into())
    }
}

#[tokio::test]
async fn long_requests_are_condensed_and_terms_are_grounded_in_results() {
    let search = Arc::new(Hits(Mutex::new(Vec::new())));
    let r = SearchResearcher::new(search.clone(), Arc::new(Model));
    let request = format!(
        "Hinglish slang that fits this message: \"{}\"",
        "x".repeat(200)
    );
    let found = r.research(&request).await.unwrap();
    assert_eq!(
        search.0.lock().unwrap().as_slice(),
        ["hinglish slang for job offer"]
    );
    assert_eq!(found.len(), 1);
    assert_eq!(found[0].term, "bawaal");
    assert_eq!(found[0].min_tier, Tier::Spicy);
}

use super::*;
use crate::conversation::{Turn, Window};
use crate::rating::Tier;
use crate::reading::{parse_reading, reading_request};
use crate::region::SlangTerm;

struct Fixed(&'static str);

#[async_trait]
impl ChatModel for Fixed {
    async fn complete(&self, _system: &str, user: &str) -> Result<String, BoxError> {
        assert!(user.contains("Questions:"));
        Ok(self.0.to_owned())
    }
}

fn slang() -> Vec<SlangTerm> {
    vec![
        SlangTerm {
            term: "yaar".into(),
            meaning: "mate".into(),
            min_tier: Tier::Light,
        },
        SlangTerm {
            term: "jugaad".into(),
            meaning: "hack".into(),
            min_tier: Tier::Light,
        },
    ]
}

#[tokio::test]
async fn llm_answers_drive_a_full_reading() {
    let reply = r#"Sure! ```json
    {"chat_intent": {"choice": "Celebration"}, "reply_intent": {"choice": "celebration"},
     "frankness": {"level": 3}, "playful": {"p": 0.8}, "serious": {"p": 0.05},
     "slang_best": {"choice": "jugaad"}, "slang_enough": {"p": 0.7}}
    ```"#;
    let eval = LlmEvaluator::new(Arc::new(Fixed(reply)));
    let request = reading_request(
        &[Turn::user("got the job!!")],
        "Congrats!",
        "India",
        &slang(),
        &[],
        Window::default(),
        false,
    );
    let response = eval.evaluate(&request).await.unwrap();
    let reading = parse_reading(&response).unwrap();
    assert_eq!(reading.chat_intent.as_str(), "celebration");
    assert!((reading.frankness - 0.75).abs() < 1e-9);
    assert_eq!(reading.slang_best.as_deref(), Some("jugaad"));
    assert_eq!(reading.slang_enough, Some(0.7));
}

#[test]
fn invalid_answers_are_dropped_not_invented() {
    let request = reading_request(
        &[Turn::user("hi")],
        "hello",
        "India",
        &slang(),
        &[],
        Window::default(),
        false,
    );
    let raw: BTreeMap<String, Value> = serde_json::from_value(json!({
        "chat_intent": {"choice": "party_time"},
        "frankness": {"level": 9},
        "playful": {"p": 1.7},
        "serious": {"p": "low"},
    }))
    .unwrap();
    let answers = decode(&request, &raw);
    assert!(!answers.contains_key("chat_intent"));
    // Out-of-range levels clamp to the scale's end.
    match answers.get("frankness") {
        Some(Answer::Score(s)) => assert_eq!(s.score, 4.0),
        other => panic!("{other:?}"),
    }
    assert!(!answers.contains_key("serious"));
    match answers.get("playful") {
        Some(Answer::Noul(n)) => assert_eq!(n.noul, 1.0),
        other => panic!("{other:?}"),
    }
}

#[test]
fn tolerant_shapes_are_accepted() {
    let request = reading_request(
        &[Turn::user("hi")],
        "hello",
        "India",
        &slang(),
        &[],
        Window::default(),
        false,
    );
    let raw: BTreeMap<String, Value> = serde_json::from_value(json!({
        "chat_intent": {"answer": "banter"},
        "frankness": {"score": "2"},
        "playful": 0.4,
        "serious": {"probability": "0.1"},
    }))
    .unwrap();
    let answers = decode(&request, &raw);
    assert!(matches!(answers.get("chat_intent"), Some(Answer::Choice(c)) if c.choice == "banter"));
    assert!(matches!(answers.get("frankness"), Some(Answer::Score(s)) if s.score == 2.0));
    assert!(matches!(answers.get("playful"), Some(Answer::Noul(n)) if n.noul == 0.4));
    assert!(matches!(answers.get("serious"), Some(Answer::Noul(n)) if (n.noul - 0.1).abs() < 1e-9));
}

use super::*;

fn meme(n: usize) -> Meme {
    Meme {
        title: format!("Meme {n}"),
        url: format!("https://m.example/{n}.gif"),
        source: "test".into(),
        meaning: None,
    }
}

#[test]
fn markers_resolve_with_cap_and_dedupe() {
    let c = [meme(1), meme(2), meme(3)];
    let (out, used) = resolve_markers(
        "yo\n[[meme:2]]\nmid [[meme:2]] [[meme:9]] [[meme:3]] [[meme:1]]\nend",
        &c,
        2,
    );
    assert_eq!(used, vec![meme(2), meme(3)]);
    assert!(out.contains("![Meme 2](https://m.example/2.gif)"));
    assert!(out.contains("![Meme 3](https://m.example/3.gif)"));
    assert!(!out.contains("[[meme"));
    assert!(!out.contains("\n\n\n"));
}

#[test]
fn no_marker_means_no_meme() {
    let (out, used) = resolve_markers("all good fam", &[meme(1)], 1);
    assert!(used.is_empty());
    assert_eq!(out, "all good fam");
}

#[test]
fn zero_budget_strips_markers() {
    let (out, used) = resolve_markers("hey [[meme:1]] there", &[meme(1)], 0);
    assert!(used.is_empty());
    assert_eq!(out, "hey  there");
}

#[test]
fn protected_content_must_survive() {
    let original = "Run `cargo test` then see https://docs.rs/x.\n```rust\nfn main() {}\n```";
    assert!(preserves_protected(
        original,
        "ngl just `cargo test` fr, peep https://docs.rs/x\n```rust\nfn main() {}\n```"
    ));
    assert!(!preserves_protected(
        original,
        "just run the tests bestie https://docs.rs/x\n```rust\nfn main() {}\n```"
    ));
    assert!(!preserves_protected(
        original,
        "`cargo test` https://docs.rs/x\n```rust\nfn main(){}\n```"
    ));
}

#[test]
fn ballooned_rewrite_is_rejected() {
    let original = "x".repeat(300);
    assert!(within_length(&original, &"y".repeat(700)));
    assert!(!within_length(&original, &"y".repeat(900)));
}

#[test]
fn wrapping_fence_is_stripped() {
    assert_eq!(strip_wrapping_fence("```markdown\nyo\n```"), "yo");
    assert_eq!(
        strip_wrapping_fence("```rust\nfn x(){}\n```"),
        "```rust\nfn x(){}\n```"
    );
}

#[test]
fn duplicate_from_the_live_run_is_repaired_keeping_the_original_line() {
    let original = "🤣🤣 bhai yeh toh classic hai!\n\n**Roast time:**\n\n- \"Bro\" bolke tune apne promotion ke chances bhi bro-friendzone kar diye 💀\n\n- Ab tera annual review: \"Outstanding performance par bro nahi bolna tha\"";
    let rewritten = "🤣🤣 arre bhai yeh toh historical moment hai!\n\nBoss ko \"bro\" bolke tune apne promotion ke chances bhi bro-friendzone kar diye 💀\n\n**Roast ka time:**\n- \"Bro\" bolke tune apne promotion ke chances bhi bro-friendzone kar diye 💀\n- Ab tera annual review: \"Outstanding performance par bro nahi bolna tha\"";
    let (out, removed) = repair_duplicates(original, rewritten);
    assert_eq!(removed, 1);
    assert_eq!(out.matches("bro-friendzone").count(), 1);
    // The copy kept is the list item that mirrors the original line.
    assert!(out.contains("- \"Bro\" bolke tune"));
    assert!(out.contains("historical moment"));
    assert!(out.contains("annual review"));
}

#[test]
fn repeats_the_original_already_had_are_left_alone() {
    let original = "Run the tests again after every change you make\nRun the tests again after every change you make";
    let (out, removed) = repair_duplicates(original, original);
    assert_eq!(removed, 0);
    assert_eq!(out, original);
}

#[test]
fn short_lines_are_never_treated_as_duplicates() {
    let (_, removed) = repair_duplicates("", "lol\nlol\nscene set hai\nscene set hai");
    assert_eq!(removed, 0);
}

#[test]
fn meme_only_puts_the_meme_after_the_first_paragraph() {
    let (out, used) = attach_meme("Big win bro!\n\nNow sign the offer letter.", &[meme(1)], 1);
    assert_eq!(used.len(), 1);
    let pos_meme = out.find("![Meme 1]").unwrap();
    assert!(pos_meme > out.find("Big win").unwrap() && pos_meme < out.find("Now sign").unwrap());
    let (out, used) = attach_meme("One paragraph only.", &[meme(1)], 0);
    assert!(used.is_empty());
    assert_eq!(out, "One paragraph only.");
}

